package com.example.markdowndesk;
public final class ReaderExportCheck {
 public static void main(String[] args){ReaderExportHarness h=new ReaderExportHarness();h.readerTypography=ReaderTypography.defaults().withFamily(ReaderTypography.Family.MONOSPACE).withHorizontalMarginPx(44);h.share(true);String exported=h.sent.extras.get("android.intent.extra.TEXT");if(!exported.equals(MarkdownRenderer.render(h.editor.text,h.palette,h.previewFontSp,h.readerTypography)))throw new AssertionError("HTML share must use actual current style");h.readerTypography=ReaderTypography.defaults();if(!h.sent.extras.get("android.intent.extra.TEXT").equals(exported))throw new AssertionError("prepared export payload changed with later style");h.share(false);if(!h.sent.extras.get("android.intent.extra.TEXT").equals(h.editor.text)||!h.sent.type.equals("text/markdown"))throw new AssertionError("plain Markdown share changed");System.out.println("Reader HTML share: 3 checks PASS on actual extracted action");}
}
